#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const long long INF = 1e18;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<long long> t(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> t[i];
    }

    // Ordena em ordem decrescente
    sort(t.begin() + 1, t.end(), greater<long long>());

    // dp[j] armazena o menor custo para formar j trios
    // Precisamos dos estados para i-1 e i-2
    // dp_prev2 corresponde a i-2, dp_prev1 a i-1, e dp_curr a i
    vector<long long> dp_prev2(k + 1, INF);
    vector<long long> dp_prev1(k + 1, INF);
    vector<long long> dp_curr(k + 1, INF);

    dp_prev2[0] = 0;
    dp_prev1[0] = 0;
    dp_curr[0] = 0;

    for (int i = 1; i <= n; ++i) {
        dp_curr[0] = 0;
        int max_j = i / 3;
        if (max_j > k) max_j = k;

        for (int j = 1; j <= max_j; ++j) {
            // Opção 1: não usar o i-ésimo elemento como parte do par (A, B)
            long long res = dp_prev1[j];

            // Opção 2: formar um par com t[i-1] e t[i]
            if (i >= 2 && dp_prev2[j - 1] != INF) {
                long long diff = t[i - 1] - t[i];
                res = min(res, dp_prev2[j - 1] + diff * diff);
            }

            dp_curr[j] = res;
        }
        for (int j = max_j + 1; j <= k; ++j) {
            dp_curr[j] = INF;
        }

        dp_prev2 = dp_prev1;
        dp_prev1 = dp_curr;
    }

    cout << dp_curr[k] << "\n";

    return 0;
}
